  const heroCopy=document.querySelector('.world-hero-copy');
  if(heroCopy) heroCopy.innerHTML='<p class="eyebrow light">SANDY D CARTER · Amsterdam-inspired watch design</p><h1 id="home-title">TIME.<br>REFINED.</h1><p class="world-hero-lead">Inspired by Amsterdam. Designed for Timelessness.</p><p>Amsterdam-inspired contemporary watch design shaped by clear geometry, balanced proportion and purposeful detail.</p><p class="hero-launch">Planned India debut · November 2026</p><div class="hero-actions"><a class="button button-light" href="our-story.html">Discover our story</a><a class="text-link light" href="shop.html">Discover the collection direction <span>↗</span></a></div>';
  const collection=document.querySelector('.collection-showcase');
